def project(g):
    rows={sha(v['row_entries']):k for k,v in g['variables'].items() if k.startswith('lyd_c2_')};removed=[]
    def walk(o):
        if isinstance(o,list):
            out=[]
            for n in o:
                if isinstance(n,dict) and isinstance(n.get('value'),list) and sha(n['value']) in rows:removed.append(rows[sha(n['value'])]);continue
                out.append(walk(n))
            return out
        if isinstance(o,dict):return {k:walk(v) for k,v in o.items()}
        return o
    return {'entries':[walk(n) if n['key']=='variables' else n for n in g['entries']],'removed_flags':removed,'exact_coverage':sorted(removed)==sorted(rows.values())}
